import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from '../test-utils'

/**
 * Example Unit Tests - Part 2
 *
 * This test suite covers 3 example files with comprehensive bidirectional testing:
 * 1. daily-data-processing-flow.now.ts - Flow with scheduled trigger, if-else logic, setFlowVariables
 * 2. new-user-onboarding-subflow.now.ts - Subflow with reference inputs, assignSubflowOutputs
 * 3. data-processing-subflow.now.ts - Subflow with forEach loops, complex inputs
 *
 * Each file has:
 * - Fluent → XML tests: Verify correct XML generation from TypeScript
 * - XML → Fluent tests: Verify correct TypeScript generation from XML
 */

describe('Example Unit Tests - Part 2', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    // ============================================================================
    // TEST FILE 1: daily-data-processing-flow.now.ts
    // ============================================================================
    describe('File 1: daily-data-processing-flow - Fluent to XML', () => {
        test('Flow with scheduled trigger and flow variables', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'daily-data-processing-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            expect(flows.length).toBeGreaterThanOrEqual(1)

            const flow = flows.find((f: any) => f.name === 'Daily Data Processing Flow')
            expect(flow).toBeDefined()
            expect(flow.type).toBe('flow')

            // Verify flow variables
            expect(merged['sys_hub_flow_variable']).toBeDefined()
            const flowVars = merged['sys_hub_flow_variable']
            expect(flowVars.length).toBeGreaterThan(0)

            // Check for specific flow variables with full details
            const dailyBatchId = flowVars.find((v: any) => v.element === 'dailyBatchId')
            expect(dailyBatchId).toBeDefined()
            expect(dailyBatchId.label).toBe('Daily Batch ID')
            expect(dailyBatchId.internal_type).toBe('string')
            expect(dailyBatchId.mandatory).toBe(true)
            expect(dailyBatchId.active).toBe(true)

            // Verify processedToday variable
            const processedToday = flowVars.find((v: any) => v.element === 'processedToday')
            expect(processedToday).toBeDefined()
            expect(processedToday.label).toBe('Items Processed Today')
            expect(processedToday.internal_type).toBe('integer')
            expect(processedToday.mandatory).toBe(true)

            // Verify isWeekend variable
            const isWeekend = flowVars.find((v: any) => v.element === 'isWeekend')
            expect(isWeekend).toBeDefined()
            expect(isWeekend.label).toBe('Is Weekend')
            expect(isWeekend.internal_type).toBe('boolean')
            expect(isWeekend.mandatory).toBe(true)
        })

        test('Flow with scheduled trigger validation', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'daily-data-processing-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            expect(flows.length).toBeGreaterThanOrEqual(1)

            const flow = flows.find((f: any) => f.name === 'Daily Data Processing Flow')
            expect(flow).toBeDefined()
            expect(flow.type).toBe('flow')
            expect(flow.run_as).toBe('system')

            // Verify and validate trigger
            expect(merged['sys_hub_trigger_instance_v2']).toBeDefined()
            const triggerInstances = merged['sys_hub_trigger_instance_v2']
            expect(triggerInstances.length).toBeGreaterThan(0)

            const trigger = triggerInstances[0]
            expect(trigger.trigger_type).toBeDefined()
            expect(trigger.trigger_inputs).toBeDefined()

            // Validate scheduled trigger inputs
            const triggerInputs = unzipInputArray(trigger.trigger_inputs)
            const val = (name: string) => findInput(triggerInputs, name)?.value

            expect(val('time')).toBeDefined()
        })

        test('Flow logic and action instances with validations', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'daily-data-processing-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow logic instances
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Verify action instances
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find and validate the log action
            const logAction = actionInstances.find(
                (action: any) => action.comment === 'Log daily processing start with assigned values'
            )
            expect(logAction).toBeDefined()

            const logInputsArr = unzipInputArray(logAction.values)
            const logInputs = (name: string) => findInput(logInputsArr, name)?.value

            expect(logInputs('log_level')).toBe('info')
            expect(logInputs('log_message')).toContain('Daily data processing started')
        })

        test('setFlowVariables with if-else logic', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'daily-data-processing-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow logic instances
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Should have setFlowVariables calls with detailed validation
            const setFlowVarsInstances = flowLogicInstances.filter(
                (fl: any) => fl.logic_definition === '4f787d1e0f9b0010ecf0cc52ff767ea0'
            )
            expect(setFlowVarsInstances.length).toBeGreaterThan(0)

            // Verify at least one setFlowVariables has proper structure
            const firstSetVars = setFlowVarsInstances[0]
            expect(firstSetVars.comment).toBeDefined()
            expect(firstSetVars.values).toBeDefined()

            // Verify values can be unzipped and contain variables
            const firstValues = unzipInputArray(firstSetVars.values) as any
            expect(firstValues.variables).toBeDefined()
            expect(Array.isArray(firstValues.variables)).toBe(true)

            // Verify if-else flow logic exists
            const ifLogic = flowLogicInstances.find(
                (fl: any) => fl.logic_definition === '4f787d1e0f9b0010ecf0cc52ff767ea1'
            )
            if (ifLogic) {
                expect(ifLogic).toBeDefined()
            }
        })
    })

    describe('File 1: daily-data-processing-flow - XML to Fluent', () => {
        test('Flow with scheduled trigger transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_258b861aabf84008836e778ed8cec1c0.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_258b861aabf84008836e778ed8cec1c0.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Flow')
            expect(content).toContain('trigger')

            // Verify flow definition
            expect(content).toContain('Flow(')
            expect(content).toContain("name: 'Daily Data Processing Flow'")

            // Verify scheduled trigger
            expect(content).toContain('trigger.scheduled.daily')
            expect(content).toContain('wfa.trigger(')

            // Verify flow variables
            expect(content).toContain('flowVariables: {')
            expect(content).toContain('IntegerColumn')

            // Verify setFlowVariables calls
            expect(content).toContain('wfa.flowLogic.setFlowVariables(')
            expect(content).toContain('_params.flowVariables')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })

    // ============================================================================
    // TEST FILE 2: new-user-onboarding-subflow.now.ts
    // ============================================================================
    describe('File 2: new-user-onboarding-subflow - Fluent to XML', () => {
        test('Subflow with reference inputs and outputs', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'new-user-onboarding-subflow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify subflow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const subflows = merged['sys_hub_flow']
            expect(subflows.length).toBeGreaterThanOrEqual(1)

            const subflow = subflows.find((s: any) => s.name === 'New User Onboarding Subflow')
            expect(subflow).toBeDefined()
            expect(subflow.type).toBe('subflow')

            // Verify inputs (2 inputs: user_sys_id, office_location)
            expect(merged['sys_hub_flow_input']).toBeDefined()
            const inputs = merged['sys_hub_flow_input']
            expect(inputs.length).toBe(2)

            // Validate user_sys_id input (reference to sys_user)
            const userInput = inputs.find((i: any) => i.element === 'user_sys_id')
            expect(userInput).toBeDefined()
            expect(userInput.label).toBe('User')
            expect(userInput.internal_type).toBe('reference')
            expect(userInput.mandatory).toBe(true)
            expect(userInput.reference).toBe('sys_user')

            // Validate office_location input (reference to cmn_location)
            const locationInput = inputs.find((i: any) => i.element === 'office_location')
            expect(locationInput).toBeDefined()
            expect(locationInput.label).toBe('Office Location')
            expect(locationInput.internal_type).toBe('reference')
            expect(locationInput.mandatory).toBe(true)
            expect(locationInput.reference).toBe('cmn_location')

            // Verify outputs (4 outputs: laptop_assigned, laptop_number, desk_assigned, desk_number)
            expect(merged['sys_hub_flow_output']).toBeDefined()
            const outputs = merged['sys_hub_flow_output']
            expect(outputs.length).toBe(4)

            // Validate laptop_assigned output
            const laptopAssignedOutput = outputs.find((o: any) => o.element === 'laptop_assigned')
            expect(laptopAssignedOutput).toBeDefined()
            expect(laptopAssignedOutput.label).toBe('Laptop Assigned')
            expect(laptopAssignedOutput.internal_type).toBe('boolean')

            // Validate laptop_number output
            const laptopNumberOutput = outputs.find((o: any) => o.element === 'laptop_number')
            expect(laptopNumberOutput).toBeDefined()
            expect(laptopNumberOutput.label).toBe('Laptop Asset Number')
            expect(laptopNumberOutput.internal_type).toBe('string')

            // Validate desk_assigned output
            const deskAssignedOutput = outputs.find((o: any) => o.element === 'desk_assigned')
            expect(deskAssignedOutput).toBeDefined()
            expect(deskAssignedOutput.label).toBe('Desk Assigned')
            expect(deskAssignedOutput.internal_type).toBe('boolean')

            // Validate desk_number output
            const deskNumberOutput = outputs.find((o: any) => o.element === 'desk_number')
            expect(deskNumberOutput).toBeDefined()
            expect(deskNumberOutput.label).toBe('Desk Asset Number')
            expect(deskNumberOutput.internal_type).toBe('string')
        })

        test('assignSubflowOutputs with reference values', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'new-user-onboarding-subflow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow logic instances
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Should have assignSubflowOutputs calls with detailed validation
            const assignOutputsInstances = flowLogicInstances.filter(
                (fl: any) => fl.logic_definition === 'df4e1945c3e232002841b63b12d3ae3e'
            )
            expect(assignOutputsInstances.length).toBeGreaterThan(0)

            // Verify at least one assignSubflowOutputs has proper structure
            const firstAssign = assignOutputsInstances[0]
            expect(firstAssign.comment).toBeDefined()
            expect(firstAssign.values).toBeDefined()

            // Verify values can be unzipped and contain outputsToAssign
            const firstValues = unzipInputArray(firstAssign.values) as any
            expect(firstValues.outputsToAssign).toBeDefined()
            expect(Array.isArray(firstValues.outputsToAssign)).toBe(true)

            // Verify output assignment has value and displayValue
            expect(firstValues.outputsToAssign.length).toBeGreaterThan(0)
            const firstOutput = firstValues.outputsToAssign[0]
            expect(firstOutput.name).toBeDefined()
            expect(firstOutput.value).toBeDefined()
        })
    })

    describe('File 2: new-user-onboarding-subflow - XML to Fluent', () => {
        test('Subflow with reference types transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_fc629d4281d849bd913e1e454cb059bf.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_fc629d4281d849bd913e1e454cb059bf.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Subflow')

            // Verify subflow definition
            expect(content).toContain('Subflow(')
            expect(content).toContain("name: 'New User Onboarding Subflow'")

            // Verify inputs section
            expect(content).toContain('inputs: {')

            // Verify outputs section
            expect(content).toContain('outputs: {')

            // Verify assignSubflowOutputs calls
            expect(content).toContain('wfa.flowLogic.assignSubflowOutputs(')
            expect(content).toContain('_params.outputs')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })

    // ============================================================================
    // TEST FILE 3: data-processing-subflow.now.ts
    // ============================================================================
    describe('File 3: data-processing-subflow - Fluent to XML', () => {
        test('Subflow with complex inputs including FlowObject and FlowArray', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'data-processing-subflow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify subflow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const subflows = merged['sys_hub_flow']
            expect(subflows.length).toBeGreaterThanOrEqual(1)

            const subflow = subflows.find((s: any) => s.name === 'Data Processing Subflow')
            expect(subflow).toBeDefined()
            expect(subflow.type).toBe('subflow')

            // Verify inputs with comprehensive validation (7 inputs total)
            expect(merged['sys_hub_flow_input']).toBeDefined()
            const inputs = merged['sys_hub_flow_input']
            expect(inputs.length).toBe(7)

            // Validate priority input (integer)
            const priorityInput = inputs.find((input: any) => input.element === 'priority')
            expect(priorityInput).toBeDefined()
            expect(priorityInput.label).toBe('Priority Level')
            expect(priorityInput.internal_type).toBe('integer')
            expect(priorityInput.mandatory).toBe(true)
            expect(priorityInput.hint).toBe('Priority level from 1-5 where 1 is highest')

            // Validate description input (string)
            const descriptionInput = inputs.find((input: any) => input.element === 'description')
            expect(descriptionInput).toBeDefined()
            expect(descriptionInput.label).toBe('Description')
            expect(descriptionInput.internal_type).toBe('string')
            expect(descriptionInput.mandatory).toBe(true)
            expect(descriptionInput.hint).toBe('Detailed description of the data to process')

            // Validate dueDate input (datetime)
            const dueDateInput = inputs.find((input: any) => input.element === 'dueDate')
            expect(dueDateInput).toBeDefined()
            expect(dueDateInput.label).toBe('Due Date')
            expect(dueDateInput.internal_type).toBe('glide_date_time')
            expect(dueDateInput.mandatory).toBe(true)
            expect(dueDateInput.hint).toBe('Date and time when processing should be completed')

            // Validate category input (string/choice)
            const categoryInput = inputs.find((input: any) => input.element === 'category')
            expect(categoryInput).toBeDefined()
            expect(categoryInput.label).toBe('Processing Category')
            expect(categoryInput.internal_type).toBe('string')
            expect(categoryInput.mandatory).toBe(true)
            expect(categoryInput.hint).toBe('Category: urgent, normal, low, maintenance')

            // Validate configuration input (object)
            const configInput = inputs.find((input: any) => input.element === 'configuration')
            expect(configInput).toBeDefined()
            expect(configInput.label).toBe('Configuration Object')
            expect(configInput.internal_type).toBe('string')
            expect(configInput.mandatory).toBe(false)

            // Validate items input (array)
            const itemsInput = inputs.find((input: any) => input.element === 'items')
            expect(itemsInput).toBeDefined()
            expect(itemsInput.label).toBe('Items to Process')
            expect(itemsInput.internal_type).toBe('string')
            expect(itemsInput.mandatory).toBe(false)

            // Validate assignedTo input (reference)
            const assignedToInput = inputs.find((input: any) => input.element === 'assignedTo')
            expect(assignedToInput).toBeDefined()
            expect(assignedToInput.label).toBe('Assigned To')
            expect(assignedToInput.internal_type).toBe('reference')
            expect(assignedToInput.mandatory).toBe(false)
            expect(assignedToInput.hint).toBe('User assigned to oversee the processing')
            expect(assignedToInput.reference).toBe('sys_user')

            // Verify action instances with datapill validations
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find log action with datapills in log_message
            const logAction = actionInstances.find(
                (action: any) => action.comment === 'Log the start of data processing'
            )
            expect(logAction).toBeDefined()

            const logInputsArr = unzipInputArray(logAction.values)
            const logInputs = (name: string) => findInput(logInputsArr, name)?.value

            expect(logInputs('log_level')).toBe('info')
            // Verify log_message contains datapills in XML format {{...}}
            const logMessage = logInputs('log_message')
            expect(logMessage).toContain('{{')
            expect(logMessage).toContain('}}')
            expect(logMessage).toContain('priority')
            expect(logMessage).toContain('category')

            // Verify forEach logic with datapill for items array
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            const forEachLogic = flowLogicInstances.find((fl: any) => fl.comment === 'Process each item in the array')
            expect(forEachLogic).toBeDefined()
            const forEachData = unzipInputArray(forEachLogic.values) as any
            const forEachItems = findInput(forEachData.inputs, 'items')?.value
            expect(forEachItems).toBeDefined()
            expect(forEachItems).toContain('{{')
            expect(forEachItems).toContain('items')

            // Verify if condition with datapill
            const ifLogic = flowLogicInstances.find((fl: any) => fl.comment === 'Check if priority is urgent (1)')
            expect(ifLogic).toBeDefined()
            const ifData = unzipInputArray(ifLogic.values) as any
            const ifCondition = findInput(ifData.inputs, 'condition')?.value
            expect(ifCondition).toBeDefined()
            expect(ifCondition).toContain('{{')
            expect(ifCondition).toContain('priority')
            expect(ifCondition).toContain('=1')

            // Verify outputs (3 outputs: resultMessage, success, processedCount)
            expect(merged['sys_hub_flow_output']).toBeDefined()
            const outputs = merged['sys_hub_flow_output']
            expect(outputs.length).toBe(3)

            // Validate resultMessage output
            const resultMessageOutput = outputs.find((output: any) => output.element === 'resultMessage')
            expect(resultMessageOutput).toBeDefined()
            expect(resultMessageOutput.label).toBe('Result Message')
            expect(resultMessageOutput.internal_type).toBe('string')

            // Validate success output
            const successOutput = outputs.find((output: any) => output.element === 'success')
            expect(successOutput).toBeDefined()
            expect(successOutput.label).toBe('Processing Successful')
            expect(successOutput.internal_type).toBe('boolean')

            // Validate processedCount output
            const processedCountOutput = outputs.find((output: any) => output.element === 'processedCount')
            expect(processedCountOutput).toBeDefined()
            expect(processedCountOutput.label).toBe('Items Processed Count')
            expect(processedCountOutput.internal_type).toBe('integer')
        })
    })

    describe('File 3: data-processing-subflow - XML to Fluent', () => {
        test('Subflow with complex inputs transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_72bd5ee93f434a028263ef70bd626b48.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_72bd5ee93f434a028263ef70bd626b48.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Subflow')
            expect(content).toContain('FlowObject')
            expect(content).toContain('FlowArray')

            // Verify subflow definition
            expect(content).toContain('Subflow(')
            expect(content).toContain("name: 'Data Processing Subflow'")

            // Verify complex inputs
            expect(content).toContain('inputs: {')
            expect(content).toContain('FlowObject(')
            expect(content).toContain('FlowArray(')

            // Verify outputs
            expect(content).toContain('outputs: {')

            // Verify assignSubflowOutputs calls
            expect(content).toContain('wfa.flowLogic.assignSubflowOutputs(')
            expect(content).toContain('_params.outputs')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })
})
